def create_annotated_satellite_map():
    """创建带标注的卫星图"""
    base_image_path = "shenzhen_satellite_base.png"
    output_path = "shenzhen_satellite_annotated.png"

    if not os.path.exists(base_image_path):
        print(f"卫星图文件不存在：{base_image_path}")
        return None

    # 打开卫星图
    img = Image.open(base_image_path).convert("RGBA")
    draw = ImageDraw.Draw(img)

    # 尝试加载中文字体
    try:
        font = ImageFont.truetype("/System/Library/Fonts/PingFang.ttc", 20)
        font_small = ImageFont.truetype("/System/Library/Fonts/PingFang.ttc", 14)
        font_bold = ImageFont.truetype("/System/Library/Fonts/PingFang.ttc", 24)
    except:
        try:
            font = ImageFont.truetype("/System/Library/Fonts/Helvetica.ttc", 20)
            font_small = ImageFont.truetype("/System/Library/Fonts/Helvetica.ttc", 14)
            font_bold = ImageFont.truetype("/System/Library/Fonts/Helvetica.ttc", 24)
        except:
            font = ImageFont.load_default()
            font_small = font
            font_bold = font

    # 绘制热点标注
    for hotspot in HOTSPOTS:
        x, y = hotspot["x"], hotspot["y"]
        color = hotspot["color"]

        # 根据严重程度选择颜色
        if color == "red":
            marker_color = (255, 0, 0, 200)
            border_color = (255, 100, 100, 255)
        else:
            marker_color = (255, 165, 0, 200)
            border_color = (255, 200, 100, 255)

        # 绘制圆圈标记
        radius = 25 if color == "red" else 20
        draw.ellipse([x - radius, y - radius, x + radius, y + radius], 
                     fill=marker_color, outline=border_color, width=3)

        # 绘制文字标签
        label = f"{hotspot['community']}\n{hotspot['type']}\n{hotspot['event_count']}起"
        bbox = draw.textbbox((0, 0), label, font=font_small)
        text_width = bbox[2] - bbox[0]
        text_height = bbox[3] - bbox[1]

        # 标签背景
        label_x = x + radius + 5
        label_y = y - text_height // 2
        draw.rectangle([label_x - 5, label_y - 5, label_x + text_width + 5, label_y + text_height + 5],
                       fill=(255, 255, 255, 220), outline=(0, 0, 0, 150))

        # 标签文字
        draw.text((label_x, label_y), label, fill=(0, 0, 0, 255), font=font_small)

    # 添加图例
    legend_x = 20
    legend_y = 20
    draw.rectangle([legend_x - 10, legend_y - 10, legend_x + 250, legend_y + 120],
                   fill=(255, 255, 255, 230), outline=(0, 0, 0, 150))

    legend_text = [
        "📍 深圳市电动自行车安全隐患热点",
        "",
        "🔴 高危热点（飞线充电）",
        "🟡 中危热点（其他类型）",
        "",
        f"共发现 {len(HOTSPOTS)} 个热点",
        f"总事件数：{sum(h['event_count'] for h in HOTSPOTS)} 起"
    ]

    for i, text in enumerate(legend_text):
        draw.text((legend_x, legend_y + i * 20), text, fill=(0, 0, 0, 255), font=font_small)

    # 添加标题
    title = "深圳市电动自行车安全隐患排查卫星图"
    title_bbox = draw.textbbox((0, 0), title, font=font_bold)
    title_width = title_bbox[2] - title_bbox[0]
    title_x = (img.width - title_width) // 2
    title_y = 10
    draw.rectangle([title_x - 20, title_y - 10, title_x + title_width + 20, title_y + 40],
                   fill=(0, 100, 200, 230), outline=(0, 50, 150, 255))
    draw.text((title_x, title_y), title, fill=(255, 255, 255, 255), font=font_bold)

    # 保存标注后的卫星图
    img = img.convert("RGB")
    img.save(output_path, "PNG")
    print(f"标注卫星图已生成：{output_path}")
    return output_path

